//! Live `hayato-theme` CSS loader with SIGUSR1 hot-reload support.

use std::path::PathBuf;

use gtk4::CssProvider;

use crate::state::home_dir;

pub fn filer_css_path() -> PathBuf {
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME")
        && !xdg.is_empty()
    {
        return PathBuf::from(xdg).join("hayato/filer.css");
    }
    home_dir().join(".config/hayato/filer.css")
}

/// Load ~/.config/hayato/filer.css (generated by `hayato theme set`), falling back
/// to rendering the active theme in-memory so first launch is always themed.
pub fn load_css_string() -> (String, bool) {
    let paths = hayato_theme::store::Paths::from_env();
    let slug = hayato_theme::store::active(&paths).unwrap_or_else(|| "tokyo-night".to_string());
    let theme_obj =
        hayato_theme::builtin::get(&slug).and_then(|raw| hayato_theme::Theme::parse(raw).ok());
    let prefer_dark = theme_obj
        .as_ref()
        .map(|t| {
            let bg = t.colors.background.0;
            let luma = 0.299 * f32::from(bg.r) + 0.587 * f32::from(bg.g) + 0.114 * f32::from(bg.b);
            luma < 128.0
        })
        .unwrap_or(true);

    if let Ok(css) = std::fs::read_to_string(filer_css_path())
        && !css.trim().is_empty()
    {
        return (css, prefer_dark);
    }

    if let Some(t) = &theme_obj
        && let Some(surf) = hayato_theme::SURFACES.iter().find(|s| s.name == "filer")
        && let Ok(rendered) =
            hayato_theme::store::render_surface(surf, t, &slug, &paths.home.to_string_lossy())
    {
        return (rendered, prefer_dark);
    }
    (String::new(), true)
}

pub fn apply_theme(provider: &CssProvider) {
    let (css, prefer_dark) = load_css_string();
    provider.load_from_data(&css);
    if let Some(settings) = gtk4::Settings::default() {
        settings.set_gtk_application_prefer_dark_theme(prefer_dark);
    }
}
